use serde_json::{Value, json};
pub fn tool_definition() -> Value {
    json!({"name":"codelia_app","description":"Operate this native Codelia workspace UI during its active parent run. list_threads returns loaded threads and cached runtime sessions. create_thread creates an unsent draft (no agent run or new workspace); a nonblank title of at most 80 characters is required; at most 64 unsent drafts are retained. select_thread focuses a loaded thread by exact thread_id (at most 256 bytes), including during the current run; it never redirects that run. Supply title only to create_thread and thread_id only to select_thread; remaining actions accept only action. status and list_threads identify the current project/worktree path. list_worktrees requests a refresh and returns cached actual Git worktrees and persistent operation records (may be stale; inspect again after refresh). create_worktree queues an asynchronous committed-base creation intent in this project; requires operation_id (1–64 lowercase letters/digits/hyphens, starting with a letter/digit), title (1–80 characters), optional base_ref (default HEAD, at most 256 bytes). Reuse the same operation_id for the same intent across retries; never assume creation succeeded from requested=true. The runtime always asks the user to confirm the exact base SHA, branch, destination and originating parent thread; this tool cannot approve it. Source dirty files stay in place. No agent/setup script starts and configured checkout filters are rejected. Only the user can open another worktree. Supply operation_id/title/base_ref only to create_worktree; list_worktrees accepts only action. status returns runtime and existing subagent task state. Use built-in task_spawn/task_list/task_status/task_cancel/task_send_message for agent orchestration, not this UI tool. Cannot approve requests, change credentials, execute arbitrary RPC, delete threads or send prompts. Empty draft tabs stay in memory; nonempty composer drafts save locally for restart recovery. thread_id changes to runtime session_id on first accepted user send. open_changes opens this workspace's read-only Git panel, without switching the human's workspace. Calls with no active run, a different run, or Stop already pending fail.","parameters":{"type":"object","properties":{"action":{"type":"string","enum":["list_threads","create_thread","select_thread","status","open_changes","list_worktrees","create_worktree"]},"title":{"type":"string","minLength":1,"maxLength":80},"thread_id":{"type":"string","minLength":1,"maxLength":256},"operation_id":{"type":"string","pattern":"^[a-z0-9][a-z0-9-]{0,63}$"},"base_ref":{"type":"string","minLength":1,"maxLength":256}},"required":["action"],"additionalProperties":false},"strict":false,"approval":"never","timeout_ms":10000})
}
